<template>
  <section class="expense-page" dir="rtl">
    <header class="page-heading"><div><p class="eyebrow">حسابداری</p><h1>مدیریت هزینه‌ها</h1><p>ثبت، پرداخت و گزارش‌گیری هزینه‌های عملیاتی کافه</p></div><div class="heading-actions"><button class="secondary" @click="categoryFormOpen = !categoryFormOpen">دسته‌بندی جدید</button><button class="primary" @click="openCreate">+ ثبت هزینه</button></div></header>
    <form v-if="categoryFormOpen" class="new-category" @submit.prevent="createCategory"><input v-model.trim="newCategory.name" placeholder="نام دسته‌بندی جدید" required maxlength="50" /><input v-model.trim="newCategory.code" placeholder="کد انگلیسی (اختیاری)" maxlength="50" /><button class="primary" :disabled="categorySaving">ذخیره دسته‌بندی</button></form>

    <div class="summary-grid" v-if="!loadingSummary"><article><span>کل هزینه‌ها</span><strong>{{ money(summary.total_expenses) }}</strong></article><article><span>پرداخت‌شده</span><strong class="success">{{ money(summary.paid_total) }}</strong></article><article><span>در انتظار پرداخت</span><strong class="warning">{{ money(summary.unpaid_total) }}</strong></article><article><span>تعداد هزینه‌ها</span><strong>{{ number(summary.expense_count) }}</strong></article></div>
    <div v-else class="summary-grid"><article v-for="index in 4" :key="index" class="skeleton"></article></div>

    <form class="filters" @submit.prevent="applyFilters"><input v-model.trim="draftFilters.search" placeholder="جستجو در عنوان، توضیحات یا شماره فاکتور" /><select v-model="draftFilters.category"><option value="">همه دسته‌ها</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}</option></select><select v-model="draftFilters.payment_status"><option value="">همه وضعیت‌ها</option><option value="paid">پرداخت‌شده</option><option value="pending">در انتظار پرداخت</option><option value="cancelled">لغو شده</option></select><JalaliDatePicker v-model="draftFilters.start_date" placeholder="از تاریخ" /><JalaliDatePicker v-model="draftFilters.end_date" placeholder="تا تاریخ" /><button class="secondary">اعمال فیلتر</button><button type="button" class="text-button" @click="resetFilters">پاک کردن</button></form>

    <div v-if="error" class="notice error">{{ error }} <button @click="load">تلاش مجدد</button></div>
    <div class="expense-content"><div class="table-card"><div class="table-top"><h2>فهرست هزینه‌ها</h2><span>{{ number(pagination.count) }} مورد</span></div><div v-if="loading" class="empty-state">در حال دریافت هزینه‌ها…</div><div v-else-if="!expenses.length" class="empty-state">هزینه‌ای با این فیلترها پیدا نشد.</div><div v-else class="table-scroll"><table><thead><tr><th>عنوان</th><th>دسته‌بندی</th><th>مبلغ</th><th>تاریخ</th><th>وضعیت</th><th>روش پرداخت</th><th>عملیات</th></tr></thead><tbody><tr v-for="expense in expenses" :key="expense.id"><td><strong>{{ expense.title }}</strong><small>{{ expense.description || 'بدون توضیحات' }}</small></td><td>{{ expense.category_display }}</td><td>{{ money(expense.amount) }}</td><td>{{ jalaliDate(expense.date) }}</td><td><span :class="['status', expense.payment_status]">{{ expense.payment_status_display }}</span></td><td>{{ expense.payment_method_display || '—' }}</td><td class="actions"><button @click="openEdit(expense)">ویرایش</button><button class="delete" @click="remove(expense)">حذف</button></td></tr></tbody></table></div><footer v-if="pagination.total_pages > 1" class="pagination"><button :disabled="!pagination.has_previous" @click="goPage(pagination.page - 1)">بعدی</button><span>صفحه {{ number(pagination.page) }} از {{ number(pagination.total_pages) }}</span><button :disabled="!pagination.has_next" @click="goPage(pagination.page + 1)">قبلی</button></footer></div>
      <aside class="report-card"><h2>تفکیک دسته‌بندی</h2><div v-if="!summary.category_breakdown?.length" class="muted">گزارشی موجود نیست.</div><div v-for="item in summary.category_breakdown" :key="item.category_id" class="breakdown"><span>{{ item.category__name }}</span><strong>{{ money(item.total) }}</strong><small>{{ number(item.count) }} هزینه</small></div><h2 class="monthly-title">روند ماهانه</h2><div v-for="row in monthly" :key="`${row.year}-${row.month}`" class="monthly"><span>{{ jalaliMonth(row.year, row.month) }}</span><strong>{{ money(row.total) }}</strong></div></aside>
    </div>
    <ExpenseModal v-model="modalOpen" :expense="editingExpense" :categories="categories" :loading="saving" :server-error="modalError" :field-errors="modalFieldErrors" @submit="save" />
    <CostToastHost />
  </section>
</template>

<script setup>
import { onMounted, reactive, ref } from 'vue'
import TransactionAPI from '@/api/transaction.api'
import ExpenseModal from '@/components/modals/ExpenseModal.vue'
import JalaliDatePicker from '@/components/cost/JalaliDatePicker.vue'
import CostToastHost from '@/components/cost/CostToastHost.vue'

const blankFilters = () => ({ search: '', category: '', payment_status: '', start_date: '', end_date: '', page: 1, page_size: 10 })
const filters = reactive(blankFilters()), draftFilters = reactive(blankFilters())
const expenses = ref([]), categories = ref([]), monthly = ref([]), loading = ref(false), loadingSummary = ref(false), saving = ref(false), error = ref(''), modalError = ref(''), modalFieldErrors = ref({}), modalOpen = ref(false), editingExpense = ref(null), categoryFormOpen = ref(false), categorySaving = ref(false)
const pagination = reactive({ count: 0, page: 1, total_pages: 1, has_next: false, has_previous: false })
const summary = reactive({ total_expenses: 0, paid_total: 0, unpaid_total: 0, expense_count: 0, category_breakdown: [] })
const newCategory = reactive({ name: '', code: '' })
const params = () => Object.fromEntries(Object.entries(filters).filter(([, value]) => value !== '' && value !== null))
const number = value => Number(value || 0).toLocaleString('fa-IR')
const money = value => `${number(value)} تومان`
const jalaliDate = value => value ? new Intl.DateTimeFormat('fa-IR-u-ca-persian', { timeZone: 'Asia/Tehran', year: 'numeric', month: 'short', day: 'numeric' }).format(new Date(value)) : '—'
const jalaliMonth = (year, month) => new Intl.DateTimeFormat('fa-IR-u-ca-persian', { timeZone: 'Asia/Tehran', year: 'numeric', month: 'long' }).format(new Date(Date.UTC(year, month - 1, 1)))
const errorText = response => response?.cost?.message || response?.message || 'ارتباط با سرور برقرار نشد.'
async function load() { loading.value = true; error.value = ''; try { const data = await TransactionAPI.getList(params()); expenses.value = data.results || []; Object.assign(pagination, data) } catch (cause) { error.value = errorText(cause) } finally { loading.value = false } }
async function loadReports() { loadingSummary.value = true; try { const [summaryResponse, monthlyResponse] = await Promise.all([TransactionAPI.getSummary(params()), TransactionAPI.getMonthlyReport(params())]); Object.assign(summary, summaryResponse); monthly.value = monthlyResponse } catch (cause) { error.value = errorText(cause) } finally { loadingSummary.value = false } }
async function loadCategories() { try { categories.value = await TransactionAPI.getCategoryList() } catch (cause) { error.value = errorText(cause) } }
async function refresh() { await Promise.all([load(), loadReports()]) }
function applyFilters() { Object.assign(filters, draftFilters, { page: 1 }); refresh() }
function resetFilters() { Object.assign(filters, blankFilters()); Object.assign(draftFilters, blankFilters()); refresh() }
function goPage(page) { filters.page = page; load() }
function openCreate() { editingExpense.value = null; modalError.value = ''; modalFieldErrors.value = {}; modalOpen.value = true }
function openEdit(expense) { editingExpense.value = expense; modalError.value = ''; modalFieldErrors.value = {}; modalOpen.value = true }
async function save(form) { saving.value = true; modalError.value = ''; modalFieldErrors.value = {}; const data = { ...form, date: `${form.date}T00:00:00` }; try { if (editingExpense.value) await TransactionAPI.partialUpdate(editingExpense.value.id, data); else await TransactionAPI.create(data); modalOpen.value = false; await refresh() } catch (cause) { modalError.value = errorText(cause); modalFieldErrors.value = cause.cost?.errors || {} } finally { saving.value = false } }
async function remove(expense) { if (!window.confirm(`هزینه «${expense.title}» حذف شود؟`)) return; try { await TransactionAPI.remove(expense.id); await refresh() } catch (cause) { error.value = errorText(cause) } }
async function createCategory() { categorySaving.value = true; try { await TransactionAPI.createCategory({ ...newCategory, color: '#8a5e3a' }); newCategory.name = ''; newCategory.code = ''; categoryFormOpen.value = false; await loadCategories() } catch (cause) { error.value = errorText(cause) } finally { categorySaving.value = false } }
onMounted(async () => { await loadCategories(); await refresh() })
</script>

<style scoped>
.expense-page{display:grid;gap:1.25rem}.page-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem}.page-heading h1{font-size:1.6rem;margin:.15rem 0}.page-heading p{color:#6b7280;margin:0}.eyebrow{font-size:.8rem!important;color:#8a5e3a!important;font-weight:700}.heading-actions,.filters,.new-category{display:flex;gap:.65rem;flex-wrap:wrap}.primary,.secondary,.text-button{border:0;border-radius:9px;padding:.65rem 1rem;font:inherit;font-weight:700;cursor:pointer}.primary{background:#8a5e3a;color:#fff}.secondary{background:#f3ece5;color:#6e4728}.text-button{background:transparent;color:#6b7280}.new-category,.filters,.table-card,.report-card{background:#fff;border:1px solid #e7dfd6;border-radius:14px;padding:1rem;box-shadow:0 4px 15px #3523150a}.new-category input,.filters input,.filters select{min-height:42px;flex:1 1 160px;border:1px solid #d9d2ca;border-radius:8px;padding:0 .75rem;background:#fff;font:inherit}.summary-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.summary-grid article{display:grid;gap:.45rem;background:#fff;border:1px solid #e7dfd6;border-radius:14px;padding:1rem}.summary-grid span{color:#6b7280;font-size:.85rem}.summary-grid strong{font-size:1.05rem;color:#3f2a1b}.summary-grid .success{color:#15803d}.summary-grid .warning{color:#b45309}.skeleton{min-height:82px;background:linear-gradient(90deg,#f4f4f5,#fafafa,#f4f4f5)!important}.notice{padding:.8rem;border-radius:9px}.error{background:#fef2f2;color:#b91c1c}.expense-content{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:1rem}.table-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem}.table-top h2,.report-card h2{font-size:1rem;margin:0}.table-top span,.muted{color:#6b7280;font-size:.85rem}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:780px;text-align:right}th{padding:.65rem;text-align:right;font-size:.8rem;color:#6b7280;border-bottom:1px solid #eee}td{padding:.8rem .65rem;border-bottom:1px solid #f1f1f1;font-size:.9rem}td small{display:block;color:#6b7280;margin-top:.2rem;max-width:220px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.status{padding:.22rem .55rem;border-radius:99px;font-size:.75rem}.status.paid{background:#dcfce7;color:#166534}.status.pending{background:#fef3c7;color:#92400e}.status.cancelled{background:#fee2e2;color:#991b1b}.actions{white-space:nowrap}.actions button{background:transparent;border:0;color:#8a5e3a;cursor:pointer;margin-left:.5rem}.actions .delete{color:#b91c1c}.empty-state{text-align:center;padding:3rem;color:#6b7280}.pagination{display:flex;align-items:center;justify-content:center;gap:1rem;padding-top:1rem}.pagination button{border:0;background:#f3ece5;color:#6e4728;border-radius:7px;padding:.4rem .7rem;cursor:pointer}.pagination button:disabled{opacity:.45;cursor:not-allowed}.report-card{height:max-content}.breakdown,.monthly{display:grid;grid-template-columns:1fr auto;gap:.25rem;padding:.8rem 0;border-bottom:1px solid #f0ece8;font-size:.85rem}.breakdown small{grid-column:1/-1;color:#6b7280}.monthly-title{margin-top:1.25rem!important}.monthly strong,.breakdown strong{font-size:.8rem;color:#6e4728}@media(max-width:1000px){.expense-content{grid-template-columns:1fr}.report-card{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:1rem}.report-card h2{grid-column:1/-1}}@media(max-width:680px){.page-heading{flex-direction:column}.summary-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.filters>*{flex-basis:100%}.report-card{grid-template-columns:1fr}.report-card h2{grid-column:auto}}
</style>
